import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Module 6: Memory Fragmentation.
 *
 * Editable starting memory and process tables sit above a final map generated by the selected
 * placement strategy.
 */
public class FragmentationPanel extends JPanel {
    /** The placement strategies available in the UI. */
    public enum Fit {
        FIRST("First Fit"), BEST("Best Fit"), NEXT("Next Fit");

        final String label;

        Fit(String label) {
            this.label = label;
        }
    }

    private final DefaultTableModel memoryModel;
    private final JTable memoryTable;
    private final DefaultTableModel processModel;
    private final JTable processTable;
    private final DefaultTableModel finalMapModel;
    private final UIKit.Section finalMapSection;

    /** Builds editable starting-map and process tables above the single final-map table. */
    public FragmentationPanel() {
        UIKit.setupModule(this);
        add(UIKit.header("Memory Fragmentation",
                "Enter the current memory map and processes, then choose a placement strategy."), BorderLayout.NORTH);

        memoryModel = UIKit.model(new String[]{"Block #", "Base Address", "Size", "Status"}, 1);
        memoryModel.addRow(new Object[]{"0", "0B", "32GB", "Free"});
        memoryModel.addRow(new Object[]{"1", "32GB", "48GB", "Free"});
        memoryModel.addRow(new Object[]{"2", "80GB", "64GB", "Free"});
        memoryModel.addRow(new Object[]{"3", "144GB", "16GB", "Free"});
        memoryTable = UIKit.table(memoryModel);
        memoryTable.getColumnModel().getColumn(3).setCellEditor(
                new DefaultCellEditor(new JComboBox<>(new String[]{"Free", "Occupied"})));

        JButton addMemoryBtn = UIKit.secondary("Add block");
        JButton removeMemoryBtn = UIKit.secondary("Remove selected");
        addMemoryBtn.addActionListener(e -> addMemoryBlock());
        removeMemoryBtn.addActionListener(e -> {
            UIKit.removeSelectedRows(memoryTable);
            renumber(memoryModel, false);
        });
        JPanel memoryBody = createTableBody(memoryTable, addMemoryBtn, removeMemoryBtn);
        UIKit.Section memorySection = new UIKit.Section("Current Memory Map", "Sizes accept B, KB, MB, GB or TB.",
                memoryBody);

        processModel = UIKit.model(new String[]{"Process #", "Name", "Size"}, 1);
        processModel.addRow(new Object[]{"1", "P1", "15GB"});
        processModel.addRow(new Object[]{"2", "P2", "30GB"});
        processModel.addRow(new Object[]{"3", "P3", "40GB"});
        processTable = UIKit.table(processModel);

        JButton addProcessBtn = UIKit.secondary("Add process");
        JButton removeProcessBtn = UIKit.secondary("Remove selected");
        addProcessBtn.addActionListener(e -> addProcess());
        removeProcessBtn.addActionListener(e -> {
            UIKit.removeSelectedRows(processTable);
            renumber(processModel, true);
        });
        JPanel processBody = createTableBody(processTable, addProcessBtn, removeProcessBtn);
        UIKit.Section processSection = new UIKit.Section("Processes", "Process sizes accept B, KB, MB, GB or TB.",
                processBody);

        JComponent inputs = UIKit.split(JSplitPane.HORIZONTAL_SPLIT, memorySection, processSection, 0.5);

        finalMapModel = UIKit.model(new String[]{"Block #", "Base Address", "Size", "Status / Process"}, false);
        JTable finalMapTable = UIKit.table(finalMapModel);
        JPanel algorithmButtons = UIKit.transparent(new FlowLayout(FlowLayout.LEFT, 8, 0));
        JButton firstFitBtn = UIKit.primary("Run First Fit");
        JButton bestFitBtn = UIKit.primary("Run Best Fit");
        JButton nextFitBtn = UIKit.primary("Run Next Fit");
        firstFitBtn.addActionListener(e -> run(Fit.FIRST));
        bestFitBtn.addActionListener(e -> run(Fit.BEST));
        nextFitBtn.addActionListener(e -> run(Fit.NEXT));
        algorithmButtons.add(firstFitBtn);
        algorithmButtons.add(bestFitBtn);
        algorithmButtons.add(nextFitBtn);

        JPanel finalMapBody = UIKit.transparent(new BorderLayout(0, 10));
        finalMapBody.add(algorithmButtons, BorderLayout.NORTH);
        finalMapBody.add(UIKit.scroll(finalMapTable), BorderLayout.CENTER);
        finalMapSection = new UIKit.Section("Final Memory Map", "Choose a placement strategy to run.", finalMapBody);

        add(UIKit.split(JSplitPane.VERTICAL_SPLIT, inputs, finalMapSection, 0.5), BorderLayout.CENTER);
    }

    private JPanel createTableBody(JTable table, JButton addButton, JButton removeButton) {
        JPanel body = UIKit.transparent(new BorderLayout(0, 10));
        body.add(UIKit.scroll(table), BorderLayout.CENTER);
        body.add(UIKit.row(addButton, removeButton), BorderLayout.SOUTH);
        return body;
    }

    private void addMemoryBlock() {
        UIKit.stopEditing(memoryTable);
        int index = memoryModel.getRowCount();
        memoryModel.addRow(new Object[]{String.valueOf(index), "", "", "Free"});
    }

    private void addProcess() {
        UIKit.stopEditing(processTable);
        int number = processModel.getRowCount() + 1;
        processModel.addRow(new Object[]{String.valueOf(number), "P" + number, ""});
    }

    private void renumber(DefaultTableModel model, boolean oneBased) {
        for (int row = 0; row < model.getRowCount(); row++) {
            model.setValueAt(String.valueOf(row + (oneBased ? 1 : 0)), row, 0);
        }
    }

    private void run(Fit fit) {
        UIKit.stopEditing(memoryTable);
        UIKit.stopEditing(processTable);

        List<MemoryBlock> blocks = readMemoryBlocks();
        if (blocks == null) return;
        List<Process> processes = readProcesses();
        if (processes == null) return;

        List<MemoryBlock> result = copyBlocks(blocks);
        List<String> unallocated = fit == Fit.NEXT
                ? allocateNextFit(result, processes)
                : allocateFit(result, processes, fit);

        result.sort(Comparator.comparingLong(block -> block.base));
        finalMapModel.setRowCount(0);
        for (int i = 0; i < result.size(); i++) {
            MemoryBlock block = result.get(i);
            finalMapModel.addRow(new Object[]{
                    String.valueOf(i),
                    UIKit.formatSize(block.base),
                    UIKit.formatSize(block.size),
                    block.allocation
            });
        }

        String hint = fit.label + " \u00b7 " + (processes.size() - unallocated.size())
                + "/" + processes.size() + " processes allocated";
        finalMapSection.setHint(hint);
        if (!unallocated.isEmpty()) {
            UIKit.error(this, fit.label + " could not allocate: " + String.join(", ", unallocated));
        }
    }

    private List<MemoryBlock> readMemoryBlocks() {
        if (memoryModel.getRowCount() == 0) {
            UIKit.error(this, "Add at least one memory block before running an allocation.");
            return null;
        }

        List<MemoryBlock> blocks = new ArrayList<>();
        for (int row = 0; row < memoryModel.getRowCount(); row++) {
            Long base = parseCellSize(memoryTable, row, 1, "Memory map");
            if (base == null) return null;
            Long size = parseCellSize(memoryTable, row, 2, "Memory map");
            if (size == null) return null;
            if (size == 0) {
                rejectCell(memoryTable, row, 2, "Memory block size must be greater than zero.");
                return null;
            }
            if (base > Long.MAX_VALUE - size) {
                rejectCell(memoryTable, row, 1, "Memory block address range is too large.");
                return null;
            }

            Object statusValue = memoryModel.getValueAt(row, 3);
            String status = statusValue == null ? "" : statusValue.toString().trim();
            if (!"Free".equals(status) && !"Occupied".equals(status)) {
                rejectCell(memoryTable, row, 3, "Memory block status must be Free or Occupied.");
                return null;
            }
            blocks.add(new MemoryBlock(row, base, size, "Occupied".equals(status), status));
        }

        blocks.sort(Comparator.comparingLong(block -> block.base));
        for (int i = 1; i < blocks.size(); i++) {
            MemoryBlock previous = blocks.get(i - 1);
            MemoryBlock current = blocks.get(i);
            if (current.base < previous.end()) {
                rejectCell(memoryTable, current.sourceRow, 1, "Memory block address ranges must not overlap.");
                return null;
            }
        }
        return blocks;
    }

    private List<Process> readProcesses() {
        List<Process> processes = new ArrayList<>();
        for (int row = 0; row < processModel.getRowCount(); row++) {
            Object nameValue = processModel.getValueAt(row, 1);
            String name = nameValue == null ? "" : nameValue.toString().trim();
            if (name.isEmpty()) {
                rejectCell(processTable, row, 1, "Process name cannot be empty.");
                return null;
            }
            Long size = parseCellSize(processTable, row, 2, "Processes");
            if (size == null) return null;
            if (size == 0) {
                rejectCell(processTable, row, 2, "Process size must be greater than zero.");
                return null;
            }
            processes.add(new Process(row + 1, name, size));
        }
        return processes;
    }

    private Long parseCellSize(JTable table, int row, int column, String tableName) {
        DefaultTableModel model = (DefaultTableModel) table.getModel();
        Object value = model.getValueAt(row, column);
        String text = value == null ? "" : value.toString().trim();
        try {
            return UIKit.parseSize(text);
        } catch (IllegalArgumentException e) {
            rejectCell(table, row, column, tableName + ": " + model.getColumnName(column)
                    + " must be a size like 4096, 4KB, 4MB, 4GB or 1TB.");
            return null;
        }
    }

    private void rejectCell(JTable table, int row, int column, String message) {
        table.changeSelection(row, column, false, false);
        table.requestFocusInWindow();
        UIKit.error(this, message);
    }

    private List<MemoryBlock> copyBlocks(List<MemoryBlock> blocks) {
        List<MemoryBlock> copies = new ArrayList<>();
        for (MemoryBlock block : blocks) {
            copies.add(new MemoryBlock(block.sourceRow, block.base, block.size, block.occupied, block.allocation));
        }
        return copies;
    }

    private List<String> allocateFit(List<MemoryBlock> blocks, List<Process> processes, Fit fit) {
        List<String> unallocated = new ArrayList<>();
        for (Process process : processes) {
            int selected = -1;
            for (int i = 0; i < blocks.size(); i++) {
                MemoryBlock block = blocks.get(i);
                if (block.occupied || block.size < process.size) continue;
                if (selected < 0 || (fit == Fit.BEST && block.size < blocks.get(selected).size)) {
                    selected = i;
                    if (fit == Fit.FIRST) break;
                }
            }
            if (selected < 0) {
                unallocated.add(process.name);
            } else {
                placeProcess(blocks, selected, process);
            }
        }
        return unallocated;
    }

    private List<String> allocateNextFit(List<MemoryBlock> blocks, List<Process> processes) {
        List<String> unallocated = new ArrayList<>();
        long nextAddress = blocks.get(0).base;
        for (Process process : processes) {
            int selected = findNextFitBlock(blocks, nextAddress, process.size);
            if (selected < 0) {
                unallocated.add(process.name);
            } else {
                MemoryBlock block = blocks.get(selected);
                placeProcess(blocks, selected, process);
                nextAddress = block.base + process.size;
            }
        }
        return unallocated;
    }

    private int findNextFitBlock(List<MemoryBlock> blocks, long nextAddress, long processSize) {
        for (int pass = 0; pass < 2; pass++) {
            for (int i = 0; i < blocks.size(); i++) {
                MemoryBlock block = blocks.get(i);
                if (block.occupied || block.size < processSize) continue;
                if (pass == 0 && block.base < nextAddress) continue;
                if (pass == 1 && block.base >= nextAddress) continue;
                return i;
            }
        }
        return -1;
    }

    private void placeProcess(List<MemoryBlock> blocks, int blockIndex, Process process) {
        MemoryBlock hole = blocks.remove(blockIndex);
        blocks.add(blockIndex, new MemoryBlock(-1, hole.base, process.size, true,
                "Process " + process.number + " (" + process.name + ")"));
        long remaining = hole.size - process.size;
        if (remaining > 0) {
            blocks.add(blockIndex + 1,
                    new MemoryBlock(-1, hole.base + process.size, remaining, false, "Free"));
        }
    }

    private static final class MemoryBlock {
        private final int sourceRow;
        private final long base;
        private final long size;
        private final boolean occupied;
        private final String allocation;

        private MemoryBlock(int sourceRow, long base, long size, boolean occupied, String allocation) {
            this.sourceRow = sourceRow;
            this.base = base;
            this.size = size;
            this.occupied = occupied;
            this.allocation = allocation;
        }

        private long end() {
            return base + size;
        }
    }

    private static final class Process {
        private final int number;
        private final String name;
        private final long size;

        private Process(int number, String name, long size) {
            this.number = number;
            this.name = name;
            this.size = size;
        }
    }
}
